use std::f64::consts::PI;

fn sine_stereo(freq: f64, amp: f64, sr: u32, secs: u32) -> Vec<f32> {
    let n = (sr as usize) * (secs as usize);
    let mut out = vec![0.0f32; n * 2];
    for i in 0..n {
        let t = i as f64 / sr as f64;
        let s = (2.0 * PI * freq * t).sin() * amp;
        out[i * 2] = s as f32;
        out[i * 2 + 1] = s as f32;
    }
    out
}

